<!DOCTYPE html><html><head><meta charset="utf-8"><style>
@page{margin:0}body{margin:0;font-family:DejaVu Sans,sans-serif;color:#123c58}header{background:#123c58;height:72pt;border-bottom:3pt solid #caaa55}header img{position:absolute;left:17pt;top:10pt;width:51pt;height:51pt}header h1{position:absolute;left:78pt;top:22pt;margin:0;font-size:15pt;color:white}header p{position:absolute;left:79pt;top:44pt;margin:0;font-size:8pt;color:#d5e3ec;letter-spacing:1pt}.photo{position:absolute;left:22pt;top:89pt;width:92pt;height:112pt;border-radius:4pt}.details{position:absolute;left:132pt;top:91pt;width:264pt}.label{font-size:6pt;letter-spacing:1pt;color:#768899;margin:0 0 6pt}.name{font-size:{{ mb_strlen($student->name) > 100 ? 6 : 9 }}pt;font-weight:bold;line-height:1.35;margin:0;overflow-wrap:break-word}.matric{position:absolute;left:132pt;top:141pt;width:264pt}.matric strong{font-size:10pt;overflow-wrap:break-word}footer{position:absolute;left:22pt;top:214pt;width:376pt;border-top:1pt solid #dfe7ed;padding-top:12pt}footer strong{font-size:8pt;letter-spacing:1pt}footer p{font-size:6pt;color:#768899;margin-top:8pt}
.verified-stamp{position:absolute;left:350pt;top:214pt;width:48pt;height:48pt}.department{position:absolute;left:132pt;top:170pt;width:264pt}.department strong{font-size:{{ max(4, min(8, 420 / max(1, mb_strlen($student->department?->name ?? '')))) }}pt}.card-meta{position:absolute;left:132pt;top:195pt;font-size:6pt;color:#768899}.card-meta strong{color:#123c58}.card-meta .expiry{margin-left:20pt}</style></head><body><header><img src="{{ $logo }}" alt="School logo"><h1>MUDIAME UNIVERSITY</h1><p>TEMPORARY STUDENT ID CARD</p></header><img class="photo" src="{{ $photo }}" alt="Student photo"><div class="details"><p class="label">STUDENT NAME</p><p class="name">{{ $student->name }}</p></div><div class="matric"><p class="label">MATRIC NUMBER</p><strong>{{ $student->matric_number }}</strong></div><div class="department"><p class="label">DEPARTMENT</p><strong>{{ $student->department?->name }}</strong></div><div class="card-meta">LEVEL <strong>{{ $student->level }} L</strong><span class="expiry">EXPIRES <strong>{{ $expiresAt?->format('d M Y') }}</strong></span></div><footer><strong>TEMPORARY IDENTIFICATION</strong><p>For student identification while awaiting a permanent university ID card.</p></footer><img class="verified-stamp" src="{{ $stamp }}" alt="Mudiame University verified stamp"></body></html>
